for (int i = 50; i <= 100; i++)
{
    if (i % 7 == 0)
    {
        Console.WriteLine($"Erste Siebenerzahl ab 50: {i}");
        break;
    }
}
// Ausgabe: Erste Siebenerzahl ab 50: 56

int summe = 0;

while (true)
{
    Console.Write("Zahl (oder ende): ");
    string eingabe = Console.ReadLine();
    if (eingabe == "ende")
    {
        break;
    }
    summe += int.Parse(eingabe);
}
Console.WriteLine($"Summe: {summe}");
// Eingaben: 3, 5, 7, ende
// Ausgabe (nach den Eingaben): Summe: 15

for (int i = 1; i <= 10; i++)
{
    if (i % 3 == 0)
    {
        continue;   // 3, 6 und 9 überspringen
    }
    Console.Write($"{i} ");
}
// Ausgabe: 1 2 4 5 7 8 10

for (int zeile = 1; zeile <= 4; zeile++)
{
    for (int stern = 1; stern <= zeile; stern++)
    {
        Console.Write("*");
    }
    Console.WriteLine();
}
// Ausgabe:
// *
// **
// ***
// ****

for (int i = 1; i <= 3; i++)
{
    for (int j = 1; j <= 3; j++)
    {
        if (j == 2)
        {
            break;   // beendet nur die innere Schleife
        }
        Console.WriteLine($"i = {i}, j = {j}");
    }
}
// Ausgabe:
// i = 1, j = 1
// i = 2, j = 1
// i = 3, j = 1

