{
    if (i == 3)
    {
        continue;
    }
    Console.Write(i);
}

for (int i = 0; i < 3; i++)
{
    for (int j = 0; j < 4; j++)
    {
        Console.Write("*");
    }
}

for (int a = 1; a <= 2; a++)
{
    for (int b = 1; b <= 5; b++)
    {
        if (b == 3)
        {
            break;
        }
        Console.Write($"{b} ");
    }
}

int i = 0;

while (i < 5)
{
    if (i == 2)
    {
        continue;
    }
    Console.Write(i);
    i++;
}
